package com.number;

public class SwapNumberWithoutThird {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
float a=12.0f;
float b=24.5f;
System.out.println("a" +a);
System.out.println("b" +b);

a=a+b;
b=a-b;
a=a-b;
System.out.println("a"+a);
System.out.println("b"+b);

	}

}
